+    agentKey,
+    agentId: agentKey === 'main' ? null : agentKey,
+    agentType: agentKey === 'main' ? null : 'general-purpose',
+    agentDescription: null,
+    toolName: 'Bash',
+    toolInputPreview: 'Q=$(pwd)/queue; rm -f "$Q"/*',
+    requestedAt: '2026-09-27T15:32:21.000Z',
