+    expect(body.pendingInputCount).toBe(1);
+    expect(body.pendingPermission).toMatchObject({ answerable: true, reason: expect.stringMatching(/^Dangerous/) });
+    expect(paneChoice).not.toHaveBeenCalled();
+  });
+});
